<script setup>import {ref,onMounted} from 'vue';import {api} from '../api';const meds=ref([]),q=ref(''),show=ref(false),bill=ref(false),f=ref({}),lines=ref([{medicineId:null,unitType:'Tablet',quantity:1}]),discountPercent=ref(0),discountAmount=ref(0);async function load(){meds.value=(await api.get('/pharmacy/medicines',{params:{q:q.value}})).data}function add(){f.value={name:'',expiryDate:'',quantityTablets:0,tabletsPerStrip:10,pricePerStrip:0,batchNumber:'',boxNumber:'',section:'',component:''};show.value=true}function edit(x){f.value={...x,expiryDate:x.expiryDate?.slice(0,10)};show.value=true}async function save(){f.value.id?await api.put('/pharmacy/medicines/'+f.value.id,f.value):await api.post('/pharmacy/medicines',f.value);show.value=false;load()}async function del(x){await api.delete('/pharmacy/medicines/'+x.id);load()}function addLine(){lines.value.push({medicineId:null,unitType:'Tablet',quantity:1})}async function createBill(){await api.post('/pharmacy/bill',{patientId:null,discountPercent:discountPercent.value,discountAmount:discountAmount.value,items:lines.value});bill.value=false;alert('Bill created. Stock reduces after full payment.')}onMounted(load)</script><template><h1>Pharmacy</h1><div class="toolbar"><button @click="add">+ Add Medicine</button><button @click="bill=true">Create Bill</button><input style="max-width:360px" v-model="q" @input="load" placeholder="Search name, batch, box, section, component"></div><table class="table"><tr><th>Name</th><th>Expiry</th><th>Qty Tablets</th><th>Strip Size</th><th>Price/Strip</th><th>Batch</th><th>Box</th><th>Section</th><th>Component</th><th></th></tr><tr v-for="x in meds"><td>{{x.name}}</td><td>{{x.expiryDate?.slice(0,10)}}</td><td>{{x.quantityTablets}}</td><td>{{x.tabletsPerStrip}}</td><td>₹{{x.pricePerStrip}}</td><td>{{x.batchNumber}}</td><td>{{x.boxNumber}}</td><td>{{x.section}}</td><td>{{x.component}}</td><td class="actions"><button @click="edit(x)">Edit</button><button class="danger-btn" @click="del(x)">Delete</button></td></tr></table><div v-if="show" class="modal-bg"><div class="modal"><h2>Medicine</h2><div class="form-grid"><label>Name<input v-model="f.name"></label><label>Expiry<input type="date" v-model="f.expiryDate"></label><label>Quantity (Tablets)<input type="number" v-model.number="f.quantityTablets"></label><label>Tablets per Strip<input type="number" v-model.number="f.tabletsPerStrip"></label><label>Price per Strip<input type="number" v-model.number="f.pricePerStrip"></label><label>Batch Number<input v-model="f.batchNumber"></label><label>Box Number<input v-model="f.boxNumber"></label><label>Section<input v-model="f.section"></label><label class="full">Component<input v-model="f.component"></label></div><div class="toolbar"><button @click="save">Save</button><button class="secondary" @click="show=false">Cancel</button></div></div></div><div v-if="bill" class="modal-bg"><div class="modal"><h2>Create Pharmacy Bill</h2><table class="table"><tr><th>Medicine</th><th>Unit</th><th>Qty</th></tr><tr v-for="l in lines"><td><select v-model.number="l.medicineId"><option v-for="m in meds" :value="m.id">{{m.name}} · {{m.batchNumber}} · {{m.quantityTablets}} tablets</option></select></td><td><select v-model="l.unitType"><option>Tablet</option><option>Strip</option></select></td><td><input type="number" v-model.number="l.quantity"></td></tr></table><div class="toolbar"><button @click="addLine">+ Medicine</button></div><div class="form-grid"><label>Discount %<input type="number" v-model.number="discountPercent"></label><label>Discount Amount<input type="number" v-model.number="discountAmount"></label></div><div class="toolbar"><button @click="createBill">Create Bill</button><button class="secondary" @click="bill=false">Cancel</button></div></div></div></template>
